    vsing=[j for j in range(W) if len(set(inp[i][j] for i in range(H)))==1]
    hsing=[i for i in range(H) if len(set(inp[i]))==1]
    if vsing and not hsing:
        j=vsing[0]; A=[r_[:j] for r_ in inp]; B=[r_[j+1:] for r_ in inp]
